```python
import math
from numbers import Real


def _pair(value, name):
    if isinstance(value, (str, bytes)):
        raise TypeError(f"{name} must be a pair")
    try:
        pair = tuple(value)
    except TypeError as exc:
        raise TypeError(f"{name} must be a pair") from exc
    if len(pair) != 2:
        raise ValueError(f"{name} must contain two values")
    return pair


def remap_points(points, source_size, target_size):
    sw, sh = _pair(source_size, "source_size")
    tw, th = _pair(target_size, "target_size")
    if any(isinstance(v, bool) or not isinstance(v, int) for v in (sw, sh, tw, th)):
        raise TypeError("sizes must contain integers")
    if min(sw, sh, tw, th) < 2:
        raise ValueError("size dimensions must be at least two")
    try:
        items = list(points)
    except TypeError as exc:
        raise TypeError("points must be iterable") from exc
    result = []
    for item in items:
        x, y = _pair(item, "point")
        if any(isinstance(v, bool) or not isinstance(v, Real) for v in (x, y)):
            raise TypeError("coordinates must be real numbers")
        if not all(math.isfinite(v) for v in (x, y)) or not (0 <= x < sw and 0 <= y < sh):
            raise ValueError("point outside source bounds")
        result.append((float(x * (tw - 1) // (sw - 1)), float(y * (th - 1) // (sh - 1))))
    return result
```

